/*
 * PostgreSQL repository (Drizzle ORM).
 *
 * All SQL is generated by Drizzle with bound parameters, so user input is never
 * concatenated into a query (SQL-injection safe). Implements the same method
 * surface as the in-memory repository used by tests.
 */
import { and, eq, or, ilike, gte, lte, desc, sql } from 'drizzle-orm'
import {
  users,
  sessions,
  contactInquiries,
  quoteRequests,
  careerApplications,
  attachments,
  activityLogs,
} from '../db/schema.js'

const TABLES = {
  contact: contactInquiries,
  quote: quoteRequests,
  career: careerApplications,
}

export function createPostgresRepository(db) {
  const table = (kind) => {
    const t = TABLES[kind]
    if (!t) throw new Error(`Unknown submission kind: ${kind}`)
    return t
  }

  return {
    // ---- users -----------------------------------------------------------
    async createUser(data) {
      const [row] = await db.insert(users).values(data).returning()
      return row
    },
    async findUserByEmail(email) {
      const [row] = await db.select().from(users).where(eq(users.email, email)).limit(1)
      return row || null
    },
    async findUserById(id) {
      const [row] = await db.select().from(users).where(eq(users.id, id)).limit(1)
      return row || null
    },
    async listUsers() {
      return db.select().from(users).orderBy(users.createdAt)
    },
    async updateUserLastLogin(id) {
      const [row] = await db
        .update(users)
        .set({ lastLoginAt: new Date(), updatedAt: new Date() })
        .where(eq(users.id, id))
        .returning()
      return row || null
    },
    async updateUserPassword(id, passwordHash, role) {
      const set = { passwordHash, updatedAt: new Date() }
      if (role) set.role = role
      const [row] = await db.update(users).set(set).where(eq(users.id, id)).returning()
      return row || null
    },

    // ---- sessions --------------------------------------------------------
    async createSession(data) {
      const [row] = await db.insert(sessions).values(data).returning()
      return row
    },
    async findSessionByTokenHash(tokenHash) {
      const [row] = await db.select().from(sessions).where(eq(sessions.tokenHash, tokenHash)).limit(1)
      return row || null
    },
    async touchSession(id) {
      await db.update(sessions).set({ lastSeenAt: new Date() }).where(eq(sessions.id, id))
    },
    async revokeSession(id) {
      await db.update(sessions).set({ revokedAt: new Date() }).where(eq(sessions.id, id))
    },
    async revokeUserSessions(userId) {
      await db
        .update(sessions)
        .set({ revokedAt: new Date() })
        .where(and(eq(sessions.userId, userId), sql`${sessions.revokedAt} is null`))
    },

    // ---- submissions -----------------------------------------------------
    async createSubmission(kind, data) {
      const [row] = await db.insert(table(kind)).values(data).returning()
      return row
    },
    async getSubmission(kind, id) {
      const t = table(kind)
      const [row] = await db.select().from(t).where(eq(t.id, id)).limit(1)
      return row || null
    },
    async listSubmissions(kind, filters = {}) {
      const t = table(kind)
      const conditions = []
      if (filters.status) conditions.push(eq(t.status, filters.status))
      if (filters.service) conditions.push(eq(t.service, filters.service))
      if (filters.archived === true) conditions.push(sql`${t.archivedAt} is not null`)
      else if (filters.archived === false) conditions.push(sql`${t.archivedAt} is null`)
      if (filters.assignedAdminId) conditions.push(eq(t.assignedAdminId, filters.assignedAdminId))
      if (filters.from) conditions.push(gte(t.createdAt, filters.from))
      if (filters.to) conditions.push(lte(t.createdAt, filters.to))
      if (filters.search) {
        const q = `%${filters.search}%`
        conditions.push(or(ilike(t.fullName, q), ilike(t.email, q), ilike(t.reference, q)))
      }
      const where = conditions.length ? and(...conditions) : undefined
      const limit = Math.min(Math.max(filters.limit || 20, 1), 100)
      const offset = Math.max(filters.offset || 0, 0)

      const items = await db
        .select()
        .from(t)
        .where(where)
        .orderBy(desc(t.createdAt))
        .limit(limit)
        .offset(offset)

      const [{ value: total }] = await db
        .select({ value: sql`count(*)::int` })
        .from(t)
        .where(where)

      return { items, total }
    },
    async updateSubmission(kind, id, patch) {
      const t = table(kind)
      const [row] = await db
        .update(t)
        .set({ ...patch, updatedAt: new Date() })
        .where(eq(t.id, id))
        .returning()
      return row || null
    },
    async findRecentSubmission(kind, { email, windowMs }) {
      const t = table(kind)
      const threshold = new Date(Date.now() - windowMs)
      const [row] = await db
        .select()
        .from(t)
        .where(and(eq(t.email, email), gte(t.createdAt, threshold)))
        .orderBy(desc(t.createdAt))
        .limit(1)
      return row || null
    },

    // ---- attachments -----------------------------------------------------
    async createAttachment(data) {
      const [row] = await db.insert(attachments).values(data).returning()
      return row
    },
    async listAttachments(kind, submissionId) {
      return db
        .select()
        .from(attachments)
        .where(and(eq(attachments.submissionKind, kind), eq(attachments.submissionId, submissionId)))
    },
    async getAttachment(id) {
      const [row] = await db.select().from(attachments).where(eq(attachments.id, id)).limit(1)
      return row || null
    },

    // ---- activity --------------------------------------------------------
    async addActivity(entry) {
      const [row] = await db.insert(activityLogs).values(entry).returning()
      return row
    },
    async listActivity(kind, submissionId) {
      return db
        .select()
        .from(activityLogs)
        .where(and(eq(activityLogs.submissionKind, kind), eq(activityLogs.submissionId, submissionId)))
        .orderBy(activityLogs.createdAt)
    },

    async ping() {
      await db.execute(sql`select 1`)
      return true
    },
  }
}

export default createPostgresRepository
